import{_ as t,c as o,b as r,o as n}from"./app-C5JbrQ64.js";const a={};function l(i,e){return n(),o("div",null,e[0]||(e[0]=[r('<p><a href="https://www.bigcommerce.com/" target="_blank" rel="noopener noreferrer">BigCommerce</a>, an eCommerce platform that provides software as a service to retailers is now integrated with the Multi-vendor Marketplace app for Shopify.</p><p>This integration will help the marketplace sellers to connect their BigCommerce stores with the admin’s Shopify store.</p><p>Using the connector, sellers selling on BigCommerce can auto-sync their products with the admin’s marketplace. Also, the sellers can import their products from BigCommerce to Shopify.</p><p>Accordingly, inventory will be managed at both ends once an order is created/updated for the seller’s product at BigCommerce or at Shopify.</p><p>You can enable the <strong>BigCommerce Connector</strong> from the “<strong>Feature App</strong>” section of the app.</p><p>Check the below video of the BigCommerce Connector feature app:</p><p>BmnShr6fcq0</p><p>Let’s dig deeper to know more about the BigCommerce Connector.</p><h3 id="how-to-enable" tabindex="-1"><a class="header-anchor" href="#how-to-enable"><span>How to Enable?</span></a></h3><p>Go to the <strong>Feature App</strong> section and enable the <strong>BigCommerce Connector</strong> feature app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/screenshot-sp-seller.webkul.com-2021.09.27-16_13_42-1-1200x590.png" alt="screenshot-sp-seller.webkul.com-2021.09.27-16_13_42-1"></p><p>Then, approve the additional charge of $25 USD/month over and above your current Multi-vendor app plan.</p><h3 id="admin-panel-configuration" tabindex="-1"><a class="header-anchor" href="#admin-panel-configuration"><span>Admin Panel Configuration</span></a></h3><p>To configure the settings, visit the admin panel <strong>Configurations</strong>&gt;&gt;<strong>Connector Configuration</strong>&gt;&gt;select the connector.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/Dashboard-Admin-1-1200x556.png" alt="connector configuration"></p><p>From here, you can configure the settings.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/09/biggcommerce-571x1024.webp" alt="admin"></p><p><strong>Note:-</strong> Once the order is created at admin shopify store for connector product then same order will be created on seller&#39;s bigcommerce store also.</p><p>Even, the admin will get a reference order number like below that will be shown order section of seller&#39;s Bigcommerce store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/02/screenshot_from_2022_12_27_12_51_33-2-1200x595.png" alt="screenshot_from_2022_12_27_12_51_33-2"></p><h2 id="product-preorder-configuration" tabindex="-1"><a class="header-anchor" href="#product-preorder-configuration"><span>Product PreOrder Configuration</span></a></h2><p>We’re excited to introduce a new feature in the <strong>BigCommerce Connector</strong> for the <strong>Shopify Multivendor Marketplace app by Webkul</strong>—<strong>Preorder Data Syncing</strong>.</p><p>This feature allows merchants to sync product preorder data between BigCommerce and Shopify seamlessly.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/01/pre-order-1200x895.webp" alt="product pre order admin panel "></p><p>Once enabled, the Multivendor Marketplace App saves the preorder data and automatically syncs it through a metafield on the Shopify admin side.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/01/preorder-admin-side-1200x414.webp" alt="perorder admin side details"></p><p>The storefront then displays the same preorder details to customers, ensuring they have accurate information about product availability.</p><p>To enable this feature, admins need to navigate to the <strong>BigCommerce Connector</strong> configuration section in the app’s admin panel.</p><p>There, users can enable the Preorder Data Sync option to begin syncing preorder details for products, ensuring seamless data integration.</p><p>To Display this information on your store you need to add the code for this on your store in the liquid file .You will get this code in the <strong>Instruction for Marketplace Navigation</strong> .</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/01/store-front-1200x895.webp" alt="bigcomm-storefront"></p><p>Copy following code into <strong>product.json &gt;&gt; sections/main-product.liquid</strong> (or product-template, if exist).</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/01/preorder-code-edited-scaled.webp" alt="BigCommerce-Preorder Data Information"></p><h3 id="seller-panel-configuration" tabindex="-1"><a class="header-anchor" href="#seller-panel-configuration"><span>Seller Panel Configuration</span></a></h3><p>Now, the seller needs to manage the configuration from the Multi-vendor seller panel. Go to seller panel <strong>Configuration</strong>&gt;&gt;<strong>BigCommerce Configuration</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/Dashboard-Seller-•-Multivendor-MarketPlace-2-1200x556.png" alt="BigCommerce configure"></p><p>The seller will configure the BigCommerce details such as store hash, unit weight, store currency, dimension unit, access token.</p><p>Moreover, the seller can choose if he/she wants to auto-sync newly added products or not.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/BigCommerce-Details-Seller-•-Multivendor-MarketPlace-1200x956.png" alt="configuration"></p><p>The sellers will get all the details from their BigCommerce stores by creating API accounts.</p><h3 id="how-to-create-an-api-account" tabindex="-1"><a class="header-anchor" href="#how-to-create-an-api-account"><span>How To Create an API Account?</span></a></h3><p>To create an API account, the seller needs to login to his/her BigCommerce store.</p><p>Now, go to <strong>Advanced Settings</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/DEMO-STORE-BigCommerce-Control-Panel-1200x549.png" alt="advanced settings"></p><p>Scroll down to get <strong>API Accounts</strong> menu. Click on it and proceed to create an API account.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/DEMO-STORE-BigCommerce-Control-Panel-1-1200x499.png" alt="API account"></p><p>Enter the following details:-</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/10/Screenshot-2021-10-05T180908.149.png" alt="BigCommerce "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/10/Screenshot-2021-10-05T181032.376.png" alt="BigCommerce "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/10/Screenshot-2021-10-05T181046.674.png" alt="BigCommerce "></p><h3 id="seller-panel-configuration-1" tabindex="-1"><a class="header-anchor" href="#seller-panel-configuration-1"><span>Seller Panel Configuration</span></a></h3><p>As soon as the admin enables the BigCommerce feature, a new sub-menu gets added to the <strong>Configuration</strong> menu of the app i.e. <strong>BigCommerce Configuration</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/Dashboard-Seller-•-Multivendor-MarketPlace-3-1200x549.png" alt="bigcommerce configuration"></p><p>Visiting the BigCommerce Connector section, the seller needs to enter the details such as store hash, weight unit, currency, dimension unit and access token.</p><p>Next in this guide, we will see how to get access token.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/BigCommerce-Details-Seller-•-Multivendor-MarketPlace-1-1200x949.png" alt="BigCommerce"></p><h3 id="how-to-get-access-token" tabindex="-1"><a class="header-anchor" href="#how-to-get-access-token"><span>How to Get Access Token?</span></a></h3><p>While creating an API account, enter the details and click the Save button. A pop-up appears from where you will get the access token.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/DEMO-STORE-BigCommerce-Control-Panel-3-1200x549.png" alt="Get access token"></p><h3 id="seller-importing-products-bigcommerce-to-shopify" tabindex="-1"><a class="header-anchor" href="#seller-importing-products-bigcommerce-to-shopify"><span>Seller Importing Products - BigCommerce to Shopify</span></a></h3><p>After all these settings, the seller will proceed to import products from his/her BigCommerce store to the admin’s Shopify store.</p><p>Clicking the <strong>Import Product</strong> button, the seller will have two methods to import products.</p><p><strong>Method 1</strong>: the seller will enter the <strong>comma-separated product IDs</strong> (that the seller wants to import).<br><strong>Method 2:</strong> Select a range and import products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/Import-Product-From-BigComerce-Seller-•-Multivendor-MarketPlace-1200x680.png" alt="Import products"></p><h3 id="auto-approve-imported-products" tabindex="-1"><a class="header-anchor" href="#auto-approve-imported-products"><span>Auto Approve Imported Products</span></a></h3><p>You can enable Auto Approve from the Admin panel &gt;&gt; Configuration &gt;&gt; Product configuration so that the Admin would automatically approve all these imported products.</p><h3 id="register-webhook" tabindex="-1"><a class="header-anchor" href="#register-webhook"><span>Register Webhook</span></a></h3><p>The seller can register or unregister BigCommerce webhooks from the seller panel. For this, login to seller panel&gt;&gt;go to BigCommerce Configuration&gt;&gt;BigCommerce Webhooks.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/Screenshot-32-1200x544.png" alt="register webhook"></p><h3 id="price-rule" tabindex="-1"><a class="header-anchor" href="#price-rule"><span>Price Rule</span></a></h3><p>Let the sellers create price rules to manage the product price of the seller’s Square up POS to the merchant’s store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/Dashboard-Seller-•-Multivendor-MarketPlace-2-1200x627.png" alt="connector price rule"></p><p>Sellers will have a new menu named <strong>Connector Price Rule</strong> in the configuration menu of the app.</p><p>From here, the seller can create price rules based on which the seller’s product price will be calculated on the merchant’s store.</p><p>Now, the seller needs to enable “Price Rule” status and select the options as increase/decrease price, the price will be changed by a fixed amount or a percentage amount,</p><p>enter the amount that needs to be changed.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/09/Price-Rule-Seller-•-Multivendor-MarketPlace-1196x1024.png" alt="price rule"></p><p>Now, enable the checkbox to update sync product’s price at the merchant’s store as per the price rule created.</p><h3 id="sync-barcode" tabindex="-1"><a class="header-anchor" href="#sync-barcode"><span>Sync Barcode</span></a></h3><p>Now the admin can allow their sellers to sync the product&#39;s Barcodes (UPC, MPN, GTIN, etc) from their Bigcommerce store to the Admin&#39;s Shopify store.</p><p>To do this, first Admin needs to enable this Configuration from Admin Panel&gt;&gt; Configuration&gt;&gt; Connector Configuration&gt;&gt;Choose Bigcommerce Connector&gt;&gt;</p><p>Enable Product Barcode Option&gt;&gt;Save Changes.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/02/Admin-panel-connector-1200x505.jpeg" alt="Admin-panel-connector"></p><p>After this is enabled, the seller can select the Barcode( MPN, GTIN, UPC, etc)</p><p>that he wants to sync with the Barcode field in Admin Shopify by navigating to Seller Panel&gt;&gt; BigCommerce Configuration&gt;&gt; Select Barcode&gt;&gt;Save.</p><h2 id="demo-details" tabindex="-1"><a class="header-anchor" href="#demo-details"><span><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/02/bigcom-mpn-seller-side-1200x581.jpeg" alt="bigcom-mpn-seller-side"> Demo Details</span></a></h2><p>Follow the below link to use the demo of Multi-vendor Marketplace app: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p><p>Thanks for reading !!</p>',88)]))}const s=t(a,[["render",l]]),p=JSON.parse('{"path":"/classic/Featured-App/Connector/BIGCOMMERCE%20CONNECTOR.html","title":"BIGCOMMERCE CONNECTOR","lang":"en-US","frontmatter":{"title":"BIGCOMMERCE CONNECTOR","description":"BIGCOMMERCE CONNECTOR","date":"2025-07-25T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"How to Enable?","slug":"how-to-enable","link":"#how-to-enable","children":[]},{"level":3,"title":"Admin Panel Configuration","slug":"admin-panel-configuration","link":"#admin-panel-configuration","children":[]},{"level":2,"title":"Product PreOrder Configuration","slug":"product-preorder-configuration","link":"#product-preorder-configuration","children":[{"level":3,"title":"Seller Panel Configuration","slug":"seller-panel-configuration","link":"#seller-panel-configuration","children":[]},{"level":3,"title":"How To Create an API Account?","slug":"how-to-create-an-api-account","link":"#how-to-create-an-api-account","children":[]},{"level":3,"title":"Seller Panel Configuration","slug":"seller-panel-configuration-1","link":"#seller-panel-configuration-1","children":[]},{"level":3,"title":"How to Get Access Token?","slug":"how-to-get-access-token","link":"#how-to-get-access-token","children":[]},{"level":3,"title":"Seller Importing Products - BigCommerce to Shopify","slug":"seller-importing-products-bigcommerce-to-shopify","link":"#seller-importing-products-bigcommerce-to-shopify","children":[]},{"level":3,"title":"Auto Approve Imported Products","slug":"auto-approve-imported-products","link":"#auto-approve-imported-products","children":[]},{"level":3,"title":"Register Webhook","slug":"register-webhook","link":"#register-webhook","children":[]},{"level":3,"title":"Price Rule","slug":"price-rule","link":"#price-rule","children":[]},{"level":3,"title":"Sync Barcode","slug":"sync-barcode","link":"#sync-barcode","children":[]}]},{"level":2,"title":"Demo Details","slug":"demo-details","link":"#demo-details","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"classic/Featured-App/Connector/BIGCOMMERCE CONNECTOR.md"}');export{s as comp,p as data};
